Definition hobjs (M : word -> option byte) (s s2 : PM.vstr) (sm : PM.strm) (p : PM.pst) (en : PEC.enc) (k : PESK.sink) : Prop :=
  vstr_at M (fb + 792) s /\ iss_at M (fb + 520) s2 sm /\ parser_at M (fb + 48) (fb + 520) p /\ L5.u64_at RSEGS M (fb + 432) (fb + 440)
  /\ enc_at M (fb + 440) fb en /\ sink_at M (fb + 496) k.

